using System;using System.Collections.Generic;using System.Linq;using System.IO;using Por.Core;
class Exit:Exception{}
class Host:IGameIoHost{public string Message;public bool KeyPressed{get{return false;}}public byte ReadKey(){return 65;}public void SoundCommand(ushort c){}public void SoundSuspend(){}public void Interrupt(byte n,Types.TInterruptRegisters r){}public void Halt(int c){throw new Exit();}public void WriteLine(string m){Message=m;}public TextWriter OpenDebugLog(string p){throw new NotSupportedException();}}
class Tests{
 static long checks;static List<string> ev=new List<string>();static void Yes(bool b,string m){checks++;if(!b)throw new Exception(m);}static sbyte S(int n){return unchecked((sbyte)n);}static byte B(int n){return unchecked((byte)n);}static string E(int x,int y,int n){return "s:"+x+":"+y+":"+n;}
 static List<string> Ring(int left,int top,int right,int bottom,int corner){left=S(left-1);top=S(top-1);right=S(right+1);bottom=S(bottom+1);int sym=276+corner*3;var want=new List<string>{E(left,top,sym),E(right,top,sym),E(left,bottom,sym),E(right,bottom,sym)};for(int x=S(left+1);x<=S(right-1);x++){want.Add(E(x,top,sym+2));want.Add(E(x,bottom,sym+2));}for(int y=S(top+1);y<=S(bottom-1);y++){want.Add(E(left,y,sym+1));want.Add(E(right,y,sym+1));}return want;}
 static void Main(){var host=new Host();GameIo.Host=host;GDVars.debugTraceEnabled=false;GDVars.gameFont=new Types.TFontArr();GDVars.video.DrawGlyph=(x,y,c,g)=>ev.Add("g:"+x+":"+y+":"+c+":"+g);GDVars.video.ClearRect=(l,t,r,b)=>ev.Add("c:"+l+":"+t+":"+r+":"+b);GDVars.dsCurrent8x8SymbolPtr2=new Types.TImgBuf{data=new byte[32]};var p=new Types.TImgBuf{width=1,height=8,count=31,imgSize=1};for(int i=0;i<31;i++)p.data[i]=(byte)i;GDVars.dsSymbolSetPtrs[4]=p;GDVars.video.ShowPic=(x,y,pic)=>ev.Add(E(x,y,256+pic.data[0]));var rng=new Random(700271);
  for(int n=0;n<1000;n++){sbyte l=S(rng.Next(256)),t=S(rng.Next(256)),r=S(rng.Next(256)),b=S(rng.Next(256));byte corner=(byte)(n%3);ev.Clear();Border.DrawBorder(l,t,r,b,corner);Yes(ev.SequenceEqual(Ring(l,t,r,b,corner)),"source signed ring/corners/edges case"+n);}
  for(int n=0;n<16000;n++){sbyte l=S(rng.Next(256)),t=S(rng.Next(256)),r=S(rng.Next(256)),b=S(rng.Next(256));int ll=Math.Max(0,(int)l),tt=Math.Max(0,(int)t),rr=Math.Min(39,(int)r),bb=Math.Min(24,(int)b);ev.Clear();Border.ClearBox(l,t,r,b);bool valid=ll<=rr&&tt<=bb;Yes(ev.Count==(valid?1:0),"clipped clear guards");if(valid)Yes(ev[0]=="c:"+ll+":"+tt+":"+rr+":"+bb,"clipped rectangle");}
  for(int n=0;n<300;n++){int l=1+rng.Next(35),t=1+rng.Next(21),r=l+rng.Next(39-l),b=t+rng.Next(24-t);string title=n%2==0?"centered title":"";ev.Clear();Border.DrawWindow((sbyte)l,(sbyte)t,(sbyte)r,(sbyte)b,(byte)(n%3),11,title);var want=new List<string>{"c:"+l+":"+t+":"+r+":"+b};want.AddRange(Ring(l,t,r,b,n%3));if(title.Length>0){int width=r-l,len=Math.Min(title.Length,width),start=l+(width-len)/2;for(int i=0;i<len;i++){int ch=title[i];if(ch>=97&&ch<=122)ch-=32;want.Add("g:"+(start+i)+":"+t+":11:"+(ch%64));}}Yes(ev.SequenceEqual(want),"DrawWindow clear/ring/center order");}
  for(int c=3;c<256;c++){ev.Clear();bool fail=false;try{Border.DrawBorder(1,1,3,3,(byte)c);}catch(Exit){fail=true;}Yes(fail&&host.Message=="Bad symbol number in Put8x8Symbol.","source invalid corner delegates fatal, no guessed fallback");}
  Console.WriteLine("Border source-derived assertions: "+checks);
 }
}
